    if (dirFile.exists() && dirFile.isDirectory()) {
        File[] files = dirFile.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isFile() && file.getName().endsWith(".jar")) {
                    try {
                        URL url = file.toURI().toURL();
                        cpV.addElement(url);
                    } catch (MalformedURLException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }
}

