    byte[] a1 = (byte[]) aObj1;
    byte[] a2 = (byte[]) aObj2;
    int len1 = a1.length;
    int len2 = a2.length;
    int lim = Math.min(len1, len2);
    int k = 0;
    while (k < lim) {
        byte c1 = a1[k];
        byte c2 = a2[k];
        if (c1 != c2) {
            return c1 - c2;
        }
        k++;
    }
